import { AnimatePresence, motion, Variants } from 'framer-motion';
import React, { forwardRef, useRef } from 'react';
import styled from 'styled-components';

import AnimationsJS from '@dynatrace/strato-design-tokens/animations-js';
import Borders from '@dynatrace/strato-design-tokens/borders';
import BoxShadows from '@dynatrace/strato-design-tokens/box-shadows';
import Colors from '@dynatrace/strato-design-tokens/colors';
import Elevations from '@dynatrace/strato-design-tokens/elevations';

import type { ModalSizeOptionsType } from './types.js';
import { FocusScope } from '../../core/components/focus-scope/FocusScope.js';
import { OverlayContainer } from '../../core/components/OverlayContainer.js';
import { useOverlayStacking } from '../../core/hooks/useOverlayStacking.js';
import { OverlayStackingProvider } from '../../core/providers/OverlayStackingProvider.js';
import type { AriaLabelingProps } from '../../core/types/a11y-props.js';
import type { WithChildren } from '../../core/types/with-children.js';
import { _useDialog } from '../hooks/useDialog.js';
import { _useOverlay } from '../hooks/useOverlay.js';

export interface BaseModalProps extends AriaLabelingProps, WithChildren {
  /**
   * Controls when the modal is shown.
   * @defaultValue false
   */
  show?: boolean;
  /**
   * Sets the size of the modal.
   * @defaultValue 'medium'
   */
  size?: ModalSizeOptionsType;
  /** Handler function that is called when the modal is closed. */
  onDismiss?: () => void;
  /**
   * Determines if you can click the backdrop to dismiss the modal.
   * If true, pressing "ESC" also dismisses the modal.
   * @defaultValue true
   */
  dismissible?: boolean;
}

// #region StyledComponents
const StyledModal = /* @__PURE__ */ styled(motion.div)<{
  $size: ModalSizeOptionsType;
}>(({ $size }) => {
  let maxWidth: string | undefined = undefined;
  switch ($size) {
    case 'small':
      maxWidth = '576px';
      break;
    case 'medium':
      maxWidth = '960px';
      break;
    case 'large':
      maxWidth = '1344px';
      break;
  }

  return {
    boxSizing: 'border-box',
    position: 'relative',
    display: 'flex',
    flexDirection: 'column',

    width: '96vw',
    maxHeight: '96vh',
    maxWidth,

    boxShadow: BoxShadows.Surface.Raised.Rest,
    borderRadius: Borders.Radius.Surface.Default,
    /* removes outline that comes with useDialog for accessibility */
    outline: 'none',
    background: Colors.Background.Surface.Default,
    overflowY: 'auto',
  };
});

const StyledBackdrop = /* @__PURE__ */ styled(motion.div)({
  position: 'fixed',
  top: 0,
  left: 0,
  width: '100%',
  height: '100%',
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  background: Colors.Background.Surface.Backdrop,
  zIndex: Elevations.Default,
});
// #endregion

/** Animation variants */
const animationVariants: Record<string, Variants> = {
  // When animating AnimatePresence where child components
  // will also need to transform, they can share the same enter/exit variant states.
  // The keys will need to be exactly the same, and the child will not need to
  // define `initial`, `animate` or `exit` variants on the component.
  backdrop: {
    enter: {
      // For the opacity we need to use the default value here. Framer motion would complain
      // about too complex values, when transitioning from two custom property values within
      // an rgba value apparently.
      opacity: 1,
      transition: {
        duration: AnimationsJS.FadeIn.Duration.Fast,
        ease: AnimationsJS.FadeIn.Easing,
      },
    },
    exit: {
      opacity: 0,
      transition: {
        duration: AnimationsJS.FadeIn.Duration.Fast,
        ease: AnimationsJS.FadeIn.Easing,
      },
    },
  },
  modal: {
    enter: {
      y: 0,
      scale: 1,
      transition: {
        duration: AnimationsJS.FadeIn.Duration.Fast,
        ease: AnimationsJS.FadeIn.Easing,
      },
    },
    exit: {
      y: '5px',
      scale: 0.98,
      transition: {
        duration: AnimationsJS.FadeIn.Duration.Fast,
        ease: AnimationsJS.FadeIn.Easing,
      },
    },
  },
};

/**
 * BaseModal component
 */
export const BaseModal = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  BaseModalProps
>((props, forwardedRef) => {
  const {
    show = false,
    size = 'medium',
    children,
    onDismiss,
    dismissible = true,
    ...remainingProps
  } = props;

  const ref = useRef(null);

  // Handle interacting outside the dialog and pressing
  // the Escape key to close the modal.
  const { overlayProps } = _useOverlay(
    {
      ...props,
      onClose: () => {
        onDismiss?.();
      },
      isOpen: show,
      isDismissible: dismissible,
      isKeyboardDismissDisabled: !dismissible,
    },
    ref,
  );

  // adds all aria labels to title and dialog as well as tabindex & role
  const { dialogProps, titleProps } = _useDialog(remainingProps);

  const overlayContainerProps = useOverlayStacking(undefined, 'overlay');

  return (
    <OverlayContainer data-testid="modal-overlay" {...overlayContainerProps}>
      <AnimatePresence>
        {show && (
          <StyledBackdrop
            data-testid="modal-backdrop"
            variants={animationVariants.backdrop}
            initial="exit"
            animate="enter"
            exit="exit"
            ref={forwardedRef}
          >
            <FocusScope contain autoFocus>
              <StyledModal
                // The react-aria spread needs to be cast to Record<string, any|unknown> as there
                // is a mismatch between lib.dom HTMLElement and the react-synthetic
                // event
                {...(overlayProps as Record<string, unknown>)}
                {...(dialogProps as Record<string, unknown>)}
                {...(titleProps as Record<string, unknown>)}
                $size={size}
                data-testid="baseModal"
                ref={ref}
                variants={animationVariants.modal}
                {...remainingProps}
              >
                <OverlayStackingProvider>{children}</OverlayStackingProvider>
              </StyledModal>
            </FocusScope>
          </StyledBackdrop>
        )}
      </AnimatePresence>
    </OverlayContainer>
  );
});

(BaseModal as typeof BaseModal & { displayName: string }).displayName =
  'BaseModal';
